  it('post226: locks wrangler.toml first/last/mid octets', () => { const d = sha256("wrangler.toml"); expect(d.slice(0, 2)).toBe("95"); expect(d.slice(-2)).toBe("f8"); expect(d.slice(28, 36)).toBe("4a0b0b87"); });
