    expect(read('test/ci-config.test.ts').includes(['describe(', "'post233 wrangler HEAVY deepen"].join(''))).toBe(false);
    expect(read('test/parser.test.ts').includes(['describe(', "'post233 wrangler HEAVY deepen"].join(''))).toBe(false);
