  it('post266: compatibility_date + KV id + domain lock edges', () => {
    const t = read('wrangler.toml');
    expect(t).toMatch(/compatibility_date\s*=\s*"2025-01-01"/);
    expect(t).toContain('id = "edb6ca4df12f4f45b40508b3dda3c432"');
    expect(t).toMatch(/pattern\s*=\s*"backlink\.fuzzywigg\.com"/);
    expect(t).not.toContain('[[durable_objects]]');
    expect(t).not.toContain('[[r2_buckets]]');
    expect(t).not.toContain('[[d1_databases]]');
    expect(t).not.toContain('[ai]');
  });
